// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DonationRecord) predicate.DonationRecord {
	return predicate.DonationRecord(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DonationRecord) predicate.DonationRecord {
	return predicate.DonationRecord(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DonationRecord) predicate.DonationRecord {
	return predicate.DonationRecord(sql.NotPredicates(p))
}
